<?php
// Installation de la mise à jour du design (s'efface toute seule après usage)
require __DIR__ . '/lib.php';
$c = cfg();
if (empty($c['setup_key']) || !hash_equals($c['setup_key'], (string) ($_GET['key'] ?? ''))) { http_response_code(403); exit('Accès refusé.'); }
$files = [
    'index.php' => '',
    'manifest.webmanifest' => '',
    'apple-touch-icon.png' => '',
    'icon-192.png' => '',
    'icon-512.png' => '',
    '.htaccess' => 'T3B0aW9ucyAtSW5kZXhlcwpBZGRUeXBlIGFwcGxpY2F0aW9uL21hbmlmZXN0K2pzb24gLndlYm1hbmlmZXN0Cg==',
];
header('Content-Type: text/plain; charset=utf-8');
$ok = 0;
foreach ($files as $name => $b64) {
    if (file_put_contents(__DIR__ . '/' . $name, base64_decode($b64)) !== false) { $ok++; echo "OK  $name\n"; } else { echo "ERREUR  $name\n"; }
}
echo $ok === count($files) ? "\nMise à jour installée.\n" : "\nProblème : certains fichiers n'ont pas été écrits.\n";
@unlink(__FILE__);
